function bestHarvest(grid: number[][]): number {
  const rows = grid.length, cols = grid[0].length;
  const go = (r: number, a: number, b: number): number => {
    const here = a === b ? grid[r][a] : grid[r][a] + grid[r][b];
    if (r === rows - 1) return here;
    let best = 0;
    for (let da = -1; da <= 1; da++)
      for (let db = -1; db <= 1; db++) {
        const na = a + da, nb = b + db;
        if (na < 0 || nb < 0 || na >= cols || nb >= cols) continue;
        best = Math.max(best, go(r + 1, na, nb));
      }
    return here + best;
  };
  return go(0, 0, cols - 1);
}

