class Solution:
    def bestHarvest(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])

        def go(r, a, b):
            here = grid[r][a] if a == b else grid[r][a] + grid[r][b]
            if r == rows - 1:
                return here
            best = 0
            for na in (a - 1, a, a + 1):
                for nb in (b - 1, b, b + 1):
                    if 0 <= na < cols and 0 <= nb < cols:
                        best = max(best, go(r + 1, na, nb))
            return here + best

        return go(0, 0, cols - 1)

