function bestHarvest(grid: number[][]): number {
  const rows = grid.length, cols = grid[0].length;
  let below: number[][] = [];
  for (let r = rows - 1; r >= 0; r--) {
    const cur = Array.from({ length: cols }, () => new Array(cols).fill(0));
    for (let a = 0; a < cols; a++)
      for (let b = 0; b < cols; b++) {
        let next = 0;
        if (r < rows - 1) {
          for (let na = a - 1; na <= a + 1; na++)
            for (let nb = b - 1; nb <= b + 1; nb++)
              if (na >= 0 && nb >= 0 && na < cols && nb < cols) next = Math.max(next, below[na][nb]);
        }
        cur[a][b] = (a === b ? grid[r][a] : grid[r][a] + grid[r][b]) + next;
      }
    below = cur;
  }
  return below[0][cols - 1];
}

