class Solution:
    def bestHarvest(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        below = None
        for r in range(rows - 1, -1, -1):
            row = grid[r]
            cur = [[0] * cols for _ in range(cols)]
            for a in range(cols):
                for b in range(cols):
                    nxt = 0
                    if below is not None:
                        for na in range(max(a - 1, 0), min(a + 2, cols)):
                            line = below[na]
                            nxt = max(nxt, max(line[max(b - 1, 0):min(b + 2, cols)]))
                    cur[a][b] = (row[a] if a == b else row[a] + row[b]) + nxt
            below = cur
        return below[0][cols - 1]

